void button_init(void)
{
	//1. Enable the clock for GPIO A
	RCC_TypeDef *pRCC= NULL;
	pRCC= RCC;
	pRCC->AHB1ENR |= 1<<0;

	//2. Set mode of PA0
	GPIO_TypeDef *pGPIOA= NULL;
	pGPIOA= GPIOA;
	pGPIOA->MODER &= ~(3<<0);

	//3. Configure speed of PA0   // no need
	//pGPIOA->OSPEEDR |= 1<<

	//4. Configure pupd of PA0     // no need
	//pGPIOA->PUPDR |= 1<<


	//5. Enable clock for SYSCFG
	pRCC->APB2ENR |= 1<<14;

	//6.Configure port selection for interrupt for EXTI
	SYSCFG_TypeDef *pSYSCFG= NULL;
	pSYSCFG= SYSCFG;

	pSYSCFG->EXTICR[0] &= ~(0xF<<0);


	//5. Configure RTSR FTSR and IMR
	EXTI_TypeDef *pEXTI=NULL;
	pEXTI= EXTI;

	pEXTI->RTSR |= 1<<0;
	pEXTI->FTSR &= ~(1<<0);

	pEXTI->IMR |=1<<0;

	NVIC_EnableIRQ(EXTI0_IRQn);


}


void uart2_init(void)
{
	//1.Clock already enabled
	GPIO_TypeDef *pGPIOA=NULL;
	pGPIOA=GPIOA;

	//2. Set PA2 mode to Alternate
	pGPIOA->MODER &= ~(3<<4);
	pGPIOA->MODER |= 2<<4;

	//3. Set PA3 mode to Alternate
	pGPIOA->MODER &= ~(3<<6);
	pGPIOA->MODER |= 2<<6;

	//4. Clear AF low register PA2 and set it to 0111=7 for AF7
	pGPIOA->AFR[0] &= ~(0xF<<8);
	pGPIOA->AFR[0] |= 7<<8;

	//5. Clear AF low register PA3 and set it to 0111=7 for AF7
	pGPIOA->AFR[0] &= ~(0xF<<12);
	pGPIOA->AFR[0] |= 7<<12;

	//6. Clear PUPD reg PA2 and set 01 for pullup
	pGPIOA->PUPDR &= ~(3<<4);
	pGPIOA->PUPDR |=1<<4;

	//7. Clear PUPD reg PA3 and set 01 for pullup
	pGPIOA->PUPDR &= ~(3<<6);
	pGPIOA->PUPDR |=1<<6;

	//8. Enable clock for USART2
	RCC_TypeDef *pRCC=NULL;
	pRCC= RCC;

	pRCC->APB1ENR |=1<<17;


	//9.Set baud rate
	USART_TypeDef *pUART2=NULL;
	pUART2= USART2;

	pUART2->BRR |=0x8B;



	//10. Set no of start bit Stop bit OVER8

	//11. Transmitter block enable
	pUART2->CR1 |=1<<3;

	//12. UART enable
	pUART2->CR1 |=1<<13;
}

void send_some_data(void)
{

	USART_TypeDef *pUART2=NULL;
	pUART2=USART2;

	uint32_t len=sizeof(some_data);

	for(uint32_t i=0;i<len;i++)
	{
	while( !(pUART2->SR & (1<<7)));
	pUART2->DR = some_data[i];
	}

}

void dma1_init(void)
{
	//1. Enable clock for DMA1
	RCC_TypeDef *pRCC=RCC;
	pRCC->AHB1ENR |=1<<21;

	//2. Identify stream and channel
	DMA_Stream_TypeDef *pSTREAM6=DMA1_Stream6;
	pSTREAM6->CR &= ~(7<<25);
	pSTREAM6->CR |= 4<<25;

	//3. Program source address
	pSTREAM6->M0AR = (uint32_t)some_data;

	//4. Program destination address
	USART_TypeDef *pUSART2=USART2;
	pSTREAM6->PAR = (uint32_t)&pUSART2->DR;

	//5. Program data width

	//6. Data transfer direction
	pSTREAM6->CR &= ~(3<<6);
	pSTREAM6->CR |= 1<<6;

	//7. Program length of data to be transferred
	pSTREAM6->NDTR = sizeof(some_data);


	//7. Program Direct mode to disable that is FIFO mode
	pSTREAM6->FCR |= 1<<2;

	//8. Program threshold level
	pSTREAM6->FCR &= ~(3<<0);
	pSTREAM6->FCR |= 3<<0;

	//9. Program burst or direct
	pSTREAM6->CR &= ~(3<<23);
	//10. program stream priority   //By default 0 low

	//11. Program source increment and no increment for destination
	   //11.a Memory increment mode set
	pSTREAM6->CR |= 1<<10;

	   //11.b Peripheral increment mode clear
	pSTREAM6->CR &= ~(1<<9);

	//12. Circular mode or normal
	     //Skip by default normal



}

void dma1_enable(void)
{
	DMA_Stream_TypeDef *pSTREAM6= DMA1_Stream6;

	//13. Enable Stream
	pSTREAM6->CR |= 1<<0;
}


void dma1_interrupt_configuration(void)
{

	DMA_Stream_TypeDef *pSTREAM6= DMA1_Stream6;

	pSTREAM6->CR |= 1<<4;  // Transfer complete interrupt enable

	pSTREAM6->CR |= 1<<3;  //Half Transfer complete

	pSTREAM6->CR |= 1<<2;  // Transfer error interrupt enable

	pSTREAM6->CR |= 1<<1;  //Direct mode error interrupt enable

	pSTREAM6->FCR |= 1<<7;  //FIFO error interrupt enable

	NVIC_EnableIRQ(DMA1_Stream6_IRQn);
}

